102	// mirrorRemotePlan is the resolved set of git-config writes `mirror use` will
103	// perform. It is computed in full before anything is written so the command can
104	// echo exactly what it is about to do (and so the planning is unit-testable
105	// without touching a repo).
106	type mirrorRemotePlan struct {
107		// remote is the remote that ends up pointing at mirrorURL.
108		remote string
109		// mirrorURL is the entire:// clone URL being adopted.
110		mirrorURL string
111		// add is true when remote does not exist yet (`git remote add` rather than
112		// `git remote set-url`).
113		add bool
114		// replacedURL is the URL remote currently holds, when it is being
115		// repointed. Empty when add is true.
116		replacedURL string
117		// preserveAs, when non-empty, is a new remote that will be created holding
118		// replacedURL so the previous URL stays reachable.
119		preserveAs string
120		// preserveSkipped names the remote replacedURL would have been kept under,
121		// when preservation was asked for but could not be done (the name is already
122		// taken). Mutually exclusive with preserveAs, and empty when preservation was
123		// never requested (`--upstream ''`). Set so the report can say out loud that
124		// the previous URL did not make it into git config — the difference matters:
125		// this is the one path where a successful-looking run drops the old URL.
126		preserveSkipped string
127		// noop is true when remote already points at mirrorURL.
128		noop bool
129	}
130	
131	// planMirrorRemote resolves what to write for a `mirror use` invocation.
132	// remotes is the set of already-configured remote names and currentURL the
133	// URL of the target remote ("" when it does not exist).
134	//
135	// upstream is the requested preserve-under name; it is honored only when the
136	// target remote is actually being repointed and the name is free. An occupied
137	// name is never clobbered — silently rewriting an existing `upstream` would be
138	// the one genuinely destructive thing this command could do — but it is recorded
139	// in preserveSkipped rather than dropped quietly, because a fork checkout
140	// (`origin` + `upstream` both already configured) hits that path by default and
141	// would otherwise see a clean ✓ while the replaced URL left git config for good.
142	func planMirrorRemote(remote, mirrorURL, currentURL, upstream string, remotes map[string]bool) mirrorRemotePlan {
143		plan := mirrorRemotePlan{remote: remote, mirrorURL: mirrorURL}
144		if !remotes[remote] {
145			plan.add = true
146			return plan
147		}
148		if strings.EqualFold(strings.TrimSpace(currentURL), mirrorURL) {
149			plan.noop = true
150			return plan
151		}
152		plan.replacedURL = currentURL
153		if upstream != "" {
154			// `remote` is known to exist in this branch, so an upstream naming it is
155			// "occupied" too and lands in the skipped case — no separate check needed.
156			if remotes[upstream] {
157				plan.preserveSkipped = upstream
158			} else {
159				plan.preserveAs = upstream
160			}
161		}
162		return plan
163	}
164	
165	// applyMirrorRemotePlan performs the plan's git-config writes. The preserve step
166	// runs first so a failure there aborts before the original URL is overwritten.
167	func applyMirrorRemotePlan(ctx context.Context, dir string, plan mirrorRemotePlan) error {
168		if plan.noop {
169			return nil
170		}
171		if plan.preserveAs != "" {
172			if _, err := gitRunner(ctx, dir, "remote", "add", plan.preserveAs, plan.replacedURL); err != nil {
173				return fmt.Errorf("preserve current %s URL as %q: %w", plan.remote, plan.preserveAs, err)
174			}
175		}
176		verb := "set-url"
177		if plan.add {
178			verb = "add"
179		}
180		if _, err := gitRunner(ctx, dir, "remote", verb, plan.remote, plan.mirrorURL); err != nil {
181			return fmt.Errorf("point remote %q at the mirror: %w", plan.remote, err)
182		}
183		return nil
184	}
